/**
 * Builds Folio's MCP App (src/mcp-app/) into one self-contained HTML page: the official App class and its
 * dependencies are bundled and inlined, because hosts load the page with no network access. The page is
 * written to src/lib/folio-app.generated.ts, which the Workers serve as ui://folio/workspace.html.
 *
 *   bun run app:build
 *
 * tests/folio-mcp.test.ts fails when the generated file is out of date with src/mcp-app/.
 */
import { buildSync } from "esbuild";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = new URL("../", import.meta.url);
const read = (path: string) => readFileSync(new URL(path, root), "utf8");
export const GENERATED_PATH = "src/lib/folio-app.generated.ts";

export function buildFolioAppHtml(): string {
  const bundle = buildSync({
    entryPoints: [fileURLToPath(new URL("src/mcp-app/folio-app.ts", root))], absWorkingDir: fileURLToPath(root),
    bundle: true, format: "iife", platform: "browser", target: "es2020", minify: true, charset: "utf8", legalComments: "none", write: false, logLevel: "silent",
  });
  const script = bundle.outputFiles[0].text.trim();
  // An inline script ends at the first "</script", wherever it appears.
  if (/<\/script/i.test(script)) throw new Error("The bundled page script contains </script>.");
  // Function replacements: the bundle contains "$" sequences that a string replacement would interpret.
  return read("src/mcp-app/folio-app.html")
    .replace("/* folio:style */", () => read("src/mcp-app/folio-app.css").trim())
    .replace("/* folio:script */", () => script);
}

export function generatedModule(html: string): string {
  return "// Generated by scripts/build-folio-app.ts from src/mcp-app/. Do not edit: change src/mcp-app/ and run `bun run app:build`.\n"
    + "// Inlines @modelcontextprotocol/ext-apps/app-with-deps, which carries its own copies of the MCP SDK and zod (all MIT); see THIRD-PARTY-NOTICES.md.\n"
    + `export const FOLIO_APP_HTML: string = ${JSON.stringify(html)};\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const html = buildFolioAppHtml();
  writeFileSync(new URL(GENERATED_PATH, root), generatedModule(html));
  console.log(`Wrote ${GENERATED_PATH}: ${html.length} characters.`);
}
